#[doc = " Returns the textual content of a doc comment block as a quoted string"]
#[doc = " That is, strips leading `///` (or `/**`, etc)"]
#[doc = " and strips the ending `*/`"]
#[doc = " And then quote the string, which is needed to convert to `tt::Literal`"]
